import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-leave.json"), "utf8"),
);
const kinds = Object.keys(contract.kinds);
const models = emitModels(contract.models, "leaveConfigKindSchema");
let go =
  '// Code generated by scripts/generate-workforce-leave.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
go += `var leaveConfigKinds=[]string{${kinds.map((k) => JSON.stringify(k)).join(",")}}\n`;
let ts = '// Generated by scripts/generate-workforce-leave.mjs.\nimport { z } from "zod";\n\n';
ts += `export const LEAVE_CONFIG_KINDS=${JSON.stringify(contract.kinds)} as const;\nexport const leaveConfigKindSchema=z.enum(${JSON.stringify(kinds)});\n`;
ts += `export const LEAVE_HOLIDAY_CATEGORIES=${JSON.stringify(contract.holiday_categories)} as const;\n`;
ts += `export const LEAVE_ACCRUALS=${JSON.stringify(contract.accruals)} as const;\nexport const LEAVE_PRORATIONS=${JSON.stringify(contract.prorations)} as const;\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/leave_types.go",
  go + models.go,
  "packages/api/src/leave-contract.ts",
  ts + models.ts,
  "leave",
);
